add_action( 'woocommerce_after_shop_loop_item', 'perfectpixel_variation_stock_in_loop', 7 );

function perfectpixel_variation_stock_in_loop() {
	global $product;
	if ( ! $product || ! $product->is_type( 'variable' ) ) {
		return;
	}
	$children = $product->get_children();
	if ( ! $children || count( $children ) > max( 1, (int) '{{loop_variations_limit}}' ) ) {
		return;
	}
	echo '<ul class="perfectpixel-loop-variations" style="list-style:none;margin:.5em 0;padding:0;font-size:.85em">';
	foreach ( $children as $child_id ) {
		$variation = wc_get_product( $child_id );
		if ( ! $variation || ! $variation->variation_is_visible() ) {
			continue;
		}
		$availability = $variation->get_availability();
		$status       = $availability['availability'] ? $availability['availability'] : ( $variation->is_in_stock() ? __( 'In stock', 'woocommerce' ) : __( 'Out of stock', 'woocommerce' ) );
		printf( '<li>%s: %s</li>', esc_html( wc_get_formatted_variation( $variation, true, false, false ) ), esc_html( wp_strip_all_tags( $status ) ) );
	}
	echo '</ul>';
}
